VOWELS = "aeiou"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())


def _translate_word(word):
    # Rule 1: words starting with "xr" or "yt" are treated as vowel words.
    if word[:2] in ("xr", "yt"):
        return word + "ay"

    # Find the end of the leading consonant cluster. The cluster ends at the
    # first vowel, or at a "y" that comes after at least one consonant
    # (Rule 4). A "qu" pair is always part of the cluster (Rule 3).
    for i, ch in enumerate(word):
        if ch in VOWELS or (ch == "y" and i > 0):
            break
        if ch == "q" and word[i + 1 : i + 2] == "u":
            i += 1
            break
    else:
        i = len(word)

    return word[i:] + word[:i] + "ay"

